function menu(){return `${title('OUR CULINARY MENU','Explore our complete selection of artisan dishes crafted with farm-fresh ingredients.<br>Calibrated architectural formulations engineered for sensory equilibrium and nutritive<br>cadence.')}<div class="page-gap"></div><div class="menu-bar wrap"><div class="filters">${[['all','ALL','24'],['burgers','BURGERS','06'],['pizzas','PIZZAS','04'],['pastas','PASTAS','04'],['mains','MAINS','04'],['desserts','DESSERTS','04'],['drinks','DRINKS','02']].map(([id,l,c],n)=>`<button data-filter="${id}" class="${n===0?'black':''}">[0${n}] ${l}<b>${c}</b></button>`).join('')}</div><label class="search">${icon('search')}<input id="menu-search" aria-label="Search catalogue" placeholder="SEARCH CATALOGUE [SKU/NAME]..."></label></div><section class="menu-main wrap"><div class="menu-grid" id="menu-grid">${dishes.map((d,n)=>dishCard(d,false,n)).join('')}</div><div class="pagination"><span id="inventory">TOTAL INVENTORY: 24 DISHES</span><div><button data-page="prev" disabled>[PREV PAGE]</button><button data-page="1" class="black">1</button><button data-page="2">2</button><button data-page="3">3</button><button data-page="next">[NEXT PAGE]</button></div></div></section>`}
const specs=rows=>`<div class="specs">${rows.map(([k,v])=>`<div class="row"><span>${k}:</span><b>${v}</b></div>`).join('')}</div>`;
function about(){return `<div class="page-gap"></div><section class="page-title about-title wrap"><div class="row"><h1>OUR STORY & CULINARY<br>HERITAGE</h1><p>Precision culinary craft paired with farm-fresh produce engineered for unforgettable experiences. Structural execution from soil to plating.</p></div></section><section class="about-intro wrap grid two">${placeholder('compass','[ WIREFRAME SCHEMATIC FRAME ]','KITCHEN CAD RECONSTRUCTION')}<div><h2>ARCHITECTURAL GASTRONOMY</h2><p>Founded under the principle that culinary execution mirrors structural design, FoodieHub eliminates speculative preparation. Every ingredient is measured, traceable, and orchestrated through a modular framework to guarantee optimal flavor density, zero nutritional decay, and repeatable perfection.</p><p>Our culinary technicians synthesize seasonal harvests with precision thermal physics. We regard the plate not as decoration, but as an engineered encounter between agricultural provenance and technical craft.</p><div class="pillars"><div class="micro">[ THREE STRUCTURAL PILLARS // CORE SPECS ]</div>${pillars()}</div></div></section><section class="team-section wrap grid three">${[['MARCUS VANDENBERG','HEAD OF CULINARY ARCHITECTURE','18+ YEARS','THERMAL SOUS-VIDE & DRY AGING','PRIMARY SUITE A'],['ELENA ROSTOVA','CONFECTIONARY & FERMENTATION LEAD','12+ YEARS','HYPER-LAMINATED PATISSERIE','LABORATORY LAB 2'],['KENJI TAKAHASHI','DIRECTOR OF HARVEST INTEGRATION','15+ YEARS','HEIRLOOM BOTANICAL REDUCTION','EXPEDITION BAY 4']].map(([n,r,e,s,t])=>`<article class="team-card"><div class="placeholder"><span class="portrait-image">IMAGE</span><div class="stamp">${icon('user')}[ PORTRAIT WIREFRAME ]</div></div><div class="team-info"><h3>${n}</h3><div class="micro">${r}</div>${specs([['OPERATIONAL EXP',e],['SIGNATURE SPECIALTY',s],['STATION SECTOR',t]])}</div></article>`).join('')}</section><section class="values wrap grid three">${[['tractor','VERIFIED PROTOCOL','100% VERIFIED FARM PARTNERSHIPS','Direct contractual relations with 24 organic agrarian cooperatives situated within a 150-mile radius. No intermediaries, no unauthorized wholesale lots.',[['ACTIVE FARMS','24 REGISTERED'],['SUPPLY AUDIT','BI-WEEKLY INSPECT'],['CARBON RUNWAY','< 150 MILES LOCAL']]],['recycle','ECO_INITIATIVE','ZERO-WASTE KITCHEN INITIATIVE','Total utilization methodology: trims and ends routed to hyper-concentrated stocks, dehydrated botanical powders, or community closed-loop composting.',[['LANDFILL DIVERSION','98.4% CERTIFIED'],['COMPOST RETURN','1,400 KG / MONTH'],['STOCK RECOVERY','100% RECYCLED']]],['shield','SAFETY RATING AAA','SAFETY CERTIFICATIONS','Full-spectrum HACCP critical control point architecture, digital infrared prep sensors, and daily independent laboratory swabs on all cutting modules.',[['HACCP SCORE','100 / 100 MAXIMUM'],['SENSOR LOGS','EVERY 15 MINUTES'],['HYGIENE GRADE','GRADE A+ ACCREDITED']]]].map(([i,b,h,p,s])=>`<article class="value-card"><div class="row">${icon(i)}<span class="badge">${b}</span></div><h3>${h}</h3><p>${p}</p>${specs(s)}</article>`).join('')}</section><div class="bottom-gap"></div>`}
