function gallery(){return `${title('OUR FOOD & AMBIENCE GALLERY','A snapshot of our kitchen creations, culinary craftsmanship, and dining atmosphere. Technical<br>monoline viewports showcasing gastronomic staging, spatial lighting cadences, and operational craft.')}<section class="gallery-main wrap"><div class="gallery-grid">${galleries.map(([h,b,i,l,p,c],n)=>`<article class="gallery-card ${c}">${h?`<div class="gallery-top"><span>${h}</span><span>${b}</span></div>`:''}<div class="placeholder" role="button" tabindex="0" data-expand="${l||h||'Kitchen schematic'}" data-expand-icon="${i}"><div class="stamp">${icon(i)}${l}</div>${n>2?`<span class="expand">${n===3?'↗ CLICK TO EXPAND HIGH-RES SPEC':n===4||n===5||n===9?'CLICK TO EXPAND SPEC':'CLICK TO EXPAND'}</span>`:''}</div><p>${n===1||n===2?`<span class="gallery-meta"><span>ASPECT: 4:3 FORMAT</span><span>CAM: ${n===1?'35MM • f/2.0':'24MM • f/2.8'}</span></span>`:''}${p}</p></article>`).join('')}</div></section><div class="bottom-gap"></div>`}
const field=(name,label,meta,type,placeholder,required=true)=>`<div class="field"><label for="${name}">${label}${required?' *':''}<span>[${meta}]</span></label><input id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${type==='date'?'value="2026-10-29"':''}></div>`;
function reservationForm(message=false){return `<form id="reservation-form" data-mode="${message?'message':'reservation'}"><div class="form-grid">${field('guest-name','GUEST NAME','FULL IDENTITY','text','e.g. Dr. Julian Vance')}${field('guest-email','EMAIL ADDRESS','CONFIRMATION PACKET','email','name@domain.com')}${field('guest-phone','PHONE NUMBER','SMS TELEMETRY','tel','+1 (555) 000-0000')}${message?'':`<div class="field"><label for="guests">NUMBER OF GUESTS *<span>[PARTY 1-10]</span></label><select id="guests">${Array.from({length:10},(_,n)=>`<option ${n===1?'selected':''}>${n+1} ${n===0?'GUEST':'GUESTS'} // ${n<4?'STANDARD BOOTH':'DINING TABLE'}</option>`).join('')}</select></div>${field('booking-date','CALENDAR DATE','YYYY-MM-DD','date','')}<div class="field"><label for="time">TIME SLOT DROPDOWN *<span>[24HR CADENCE]</span></label><select id="time">${['11:00','12:30','14:00','15:30','17:00','18:30','20:00','21:30'].map(t=>`<option ${t==='18:30'?'selected':''}>${t} HRS // ${t==='18:30'?'FIRST DINING SITTING':'DINING SITTING'}</option>`).join('')}</select></div>`}<div class="field full"><label for="notes">${message?'YOUR MESSAGE *':'SPECIAL SEATING NOTES & DIETARY PROTOCOLS'}<span>[${message?'MESSAGE PACKET':'OPTIONAL / 500 CHARS'}]</span></label><textarea id="notes" maxlength="500" ${message?'required':''} placeholder="${message?'Write your inquiry here...':'Indicate allergies, seating quadrant preferences (Window, Kitchen View, Quiet Corner), or anniversary announcements...'}"></textarea></div></div>${message?'':`<div class="booking-note row"><span>ⓘ &nbsp; TABLE SELECTION: AUTOMATIC MONOLINE CAD OPTIMIZATION</span><b>GRACE PERIOD: 15 MINS</b></div>`}<div class="booking-actions row"><span class="security">♙ &nbsp;[ENCRYPTION: 256-BIT SSL TERMINAL]</span><button class="black">${message?'SEND MESSAGE':'CONFIRM TABLE RESERVATION →'}</button></div></form>`}
function contact(){return `${title('GET IN TOUCH & TABLE<br>RESERVATIONS','We would love to host your next meal or cater your special event with culinary<br>precision. Direct telemetry and table booking protocols below.','contact-title')}<section class="contact-main grid wrap"><div>${info()}<div class="map-box">${map()}<div class="map-foot row"><span>PARKING AVAILABILITY:</span><a href="https://maps.google.com/?q=Central+Gastronomic+Plaza" target="_blank" rel="noopener">OPEN EXTERNAL GPS VECTOR &nbsp; ↗</a></div></div><div class="catering"><h4>CATERING & PRIVATE SALON PROTOCOL</h4><p>For executive gatherings greater than 10 seats, dietary pre-sequencing or specialized culinary curation, dispatch requirements to our chef directorate via the dispatch terminal or electronic comms packet.</p></div></div><div class="reservation"><div class="tabs"><button class="black" data-tab="book">■ &nbsp;[01] BOOK A TABLE <span>ACTIVE DISPATCH</span></button><button data-tab="message">SEND A MESSAGE</button></div><div id="reservation-body">${reservationForm()}</div></div></section><section class="stats wrap grid four">${[['PEAK SEATING','120 SEATS','Main Dining, Salon & Chef Counter'],['TURN TIMING','90 MINS','Standard Tasting Sequence Cadence'],['CELLAR NODES','450+ SKU','Temperature Regulated Biodynamic Stock'],['PROTOCOL CODE','ISO-22000','Gastronomic Hygiene Verified']].map(([k,v,p])=>`<div class="stat"><span class="micro">${k}</span><strong>${v}</strong><p>${p}</p></div>`).join('')}</section><div class="contact-after"></div>`}
document.querySelector('#app').innerHTML=({home,menu,about,offers:offerPage,gallery,contact}[page])();
const modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');
function showModal(html){content.innerHTML=html;modal.showModal()}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}
document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
let cart=JSON.parse(localStorage.getItem('foodiehub-cart')||'[]');
document.addEventListener('click',e=>{const cartBtn=e.target.closest('[data-cart]');if(cartBtn){cart.push(cartBtn.dataset.cart);localStorage.setItem('foodiehub-cart',JSON.stringify(cart));toast(`${cartBtn.dataset.cart} added to cart (${cart.length})`)}const auth=e.target.closest('[data-auth]');if(auth)showModal(`<h2>${auth.dataset.auth.toUpperCase()}</h2><p>Account services are not connected in this design preview.</p>${cart.length?`<h3>YOUR CART (${cart.length})</h3><p>${cart.map(x=>x.replace(/[<>]/g,'')).join('<br>')}</p><button id="clear-cart">CLEAR CART</button>`:'<p>Your cart is empty.</p>'}`);if(e.target.closest('#clear-cart')){cart=[];localStorage.removeItem('foodiehub-cart');modal.close();toast('Cart cleared')}const expand=e.target.closest('[data-expand]');if(expand)showModal(`<h2>${expand.dataset.expand}</h2>${placeholder(expand.dataset.expandIcon||'burger',expand.dataset.expand)}<p>SCHEMATIC WIREFRAME // HIGH-RES SPEC</p>`);const tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('black',t===tab));document.querySelector('#reservation-body').innerHTML=reservationForm(tab.dataset.tab==='message')}const claim=e.target.closest('[data-claim]');if(claim){document.querySelector('#promo-code').value=claim.dataset.claim;document.querySelector('#promo-form').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#promo-code').focus()}const zoom=e.target.closest('[data-zoom]');if(zoom){let pin=zoom.closest('.map').querySelector('.map-pin');let z=Math.max(.6,Math.min(1.8,Number(pin.dataset.scale||1)+Number(zoom.dataset.zoom)*.2));pin.dataset.scale=z;pin.style.transform=`scale(${z})`}if(e.target.closest('#dossier'))showModal('<h2>PRIVATE BANQUET INQUIRY</h2><p>For custom tasting courses and private receptions, contact our concierge through the booking terminal.</p><a href="contact.html"><button class="black">CONTACT CONCIERGE →</button></a>')});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-expand]')){e.preventDefault();e.target.click()}});
document.addEventListener('submit',e=>{if(e.target.matches('.local-message,#reservation-form')){e.preventDefault();showModal(`<h2>${e.target.dataset.mode==='reservation'?'RESERVATION REQUEST PREPARED':'MESSAGE PREPARED'}</h2><p>This is a design preview. Your ${e.target.dataset.mode==='reservation'?'reservation':'message'} has not been sent to a restaurant.</p><button class="black" onclick="document.querySelector('#modal').close()">RETURN</button>`)}if(e.target.id==='promo-form'){e.preventDefault();const code=document.querySelector('#promo-code').value.trim().toUpperCase();document.querySelector('#promo-status').textContent=code==='FAMILY25'?'✓ FAMILY25 VERIFIED // 25% OFF FAMILY FEAST':code==='TASTE150'?'✓ TASTE150 VERIFIED // ₹150 OFF • MIN BASKET ₹499':'ⓘ CODE NOT RECOGNIZED // CHECK & RETRY'}});
let activeFilter='all',currentPage=1;
function updateMenu(){const query=document.querySelector('#menu-search').value.trim().toLowerCase();let filtered=dishes.filter(d=>(activeFilter==='all'||d[4]===activeFilter)&&`${d[0]} ${d[1]}`.toLowerCase().includes(query));if(currentPage>1&&activeFilter==='all'&&!query)filtered=currentPage===2?dishes.slice(0,8):dishes.slice(0,7);document.querySelector('#menu-grid').innerHTML=filtered.length?filtered.map((d,n)=>dishCard(d,false,n)).join(''):'<p class="empty">No dishes match your search.</p>';document.querySelector('#inventory').textContent=activeFilter==='all'&&!query?'TOTAL INVENTORY: 24 DISHES':`${filtered.length} DISHES FOUND`;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('black',Number(b.dataset.page)===currentPage);b.disabled=b.dataset.page==='prev'&&currentPage===1||b.dataset.page==='next'&&currentPage===3})}
if(page==='menu'){document.querySelector('#menu-search').addEventListener('input',()=>{currentPage=1;updateMenu()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;currentPage=1;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('black',x===b));updateMenu()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.page==='next'?Math.min(3,currentPage+1):b.dataset.page==='prev'?Math.max(1,currentPage-1):Number(b.dataset.page);updateMenu();document.querySelector('.menu-bar').scrollIntoView({behavior:'smooth'})})}
